1	// The coordinator's real tool backend (DESIGN.md §"Coordinator tools"). Each method adapts a module that exists:
2	// ingest and the review's scorecard, replayable tasks from the repo's checkpoints, replays through src/replay/run.ts,
3	// failure codes from src/grade/taxonomy.ts, the deterministic gate in src/gate, and the promotion record in
4	// reports/<slug>/promotion.json. Opening a pull request is a separate command and is not done here.
5	//
6	// Replay rows live in memory for the run and in the state database when one is given (table `replays`), so a
7	// resumed run reads back what the earlier process produced.
8	import { Database } from "bun:sqlite";
9	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
10	import { dirname, join, resolve } from "node:path";
11	import { identify } from "../identity/index.ts";
12	import { fetchCheckpoints } from "../ingest/fetch.ts";
13	import { parseCheckpoints } from "../ingest/parse.ts";
14	import { discordant, gate as decideGate, MAX_ATTEMPTS } from "../gate/index.ts";
15	import type { GradeResult } from "../grade/index.ts";
16	import { type Classified, classify, parseTranscript, type Transcript } from "../grade/taxonomy.ts";
17	import { reviewSlug, summarizeSetups } from "../review/export.ts";
18	import { defaultWorkRoot, replayRunner, runReplays, type ReplayRunnerDeps, type SkippedRun } from "../replay/run.ts";
19	import { buildReplayTasks, type ReplayTask } from "../replay/tasks.ts";
20	import { loadSetups } from "../setups/registry.ts";
21	import { runGit } from "../sandbox/index.ts";
22	import { FailureCode, type Outcome, type Replay, type Review, type Session } from "../types.ts";
23	import { NotAvailableError, type ReplayBatch, type TaskSummary, type ToolBackend, ToolError } from "./tools.ts";
24	
25	export interface DefaultBackendOptions {
26	  cacheDir?: string;
27	  /** Where review files and promotion.json go. Default "reports". */
28	  reportsDir?: string;
29	  /** The coordinator's state database. Replay rows are written here too when given. */
30	  dbPath?: string;
31	  /** What the replay runner needs: the repo under review, plus optional overrides (setups root, work root, harness). */
32	  replay?: Omit<ReplayRunnerDeps, "cacheDir">;
33	}
34	
35	const BRANCH_REFS = ["refs/heads/entire/checkpoints/v1", "refs/remotes/origin/entire/checkpoints/v1"];
36	const REMOTE = /^[a-z][a-z0-9+.-]*:\/\/|^[^/\s]+@[^/\s]+:/i;
37	const FAILURE_ORDER: string[] = Object.values(FailureCode);
38	
39	function tryGit(repo: string, args: string[]): string | null {
40	  try {
41	    return runGit(repo, args);
42	  } catch {
43	    return null;
44	  }
45	}
46	
47	/** Session turn counts from the checkpoint metadata on the branch (`session_metrics.turn_count`); null when absent. */
48	function turnCounter(repo: string): (checkpointId: string, sessionId: string) => number | null {
49	  const ref = BRANCH_REFS.find((r) => tryGit(repo, ["rev-parse", "--verify", "-q", r]) !== null);
50	  const show = (path: string): any => {
51	    const out = ref ? tryGit(repo, ["show", `${ref}:${path}`]) : null;
52	    try {
53	      return out === null ? null : JSON.parse(out);
54	    } catch {
55	      return null;
56	    }
57	  };
58	  return (checkpointId, sessionId) => {
59	    const dir = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
60	    const root = show(`${dir}/metadata.json`);
61	    const n = Array.isArray(root?.sessions) ? root.sessions.length : 0;
62	    for (let i = 0; i < n; i++) {
63	      const meta = show(`${dir}/${i}/metadata.json`);
64	      if (meta?.session_id === sessionId) {
65	        const turns = meta.session_metrics?.turn_count;
66	        return typeof turns === "number" ? turns : null;
67	      }
68	    }
69	    return null;
70	  };
71	}
72	
73	interface RepoTasks {
74	  repoPath: string;
75	  sessions: Session[];
76	  tasks: ReplayTask[];
77	}
78	
79	/** The repo's checkpoints as replayable tasks, resolved the way the replay runner resolves them. */
80	async function loadRepo(repo: string, cacheDir: string, outcomes: Outcome[]): Promise<RepoTasks> {
81	  if (!REMOTE.test(repo) && !existsSync(resolve(repo))) throw new Error(`no such repo: ${repo}`);
82	  const f = await fetchCheckpoints(repo, { cacheDir });
83	  if (f.backend === "none") throw new Error("no Entire checkpoints found in this repo");
84	  const sessions: Session[] = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch").map((s) => ({
85	    ...s,
86	    setup_id: identify(s, f.repoPath).setupId,
87	  }));
88	  return { repoPath: f.repoPath, sessions, tasks: buildReplayTasks(f.repoPath, sessions, outcomes) };
89	}
90	
91	const TERCILE_ORDER = [1, 2, 3, null] as const;
92	const TRACK_ORDER: TaskSummary["track"][] = ["tests", "judge-only"];
93	
94	/** FNV-1a, 32 bits: a stable hash, so the sample depends only on the seed and the task ids. */
95	function hash32(s: string): number {
96	  let h = 0x811c9dc5;
97	  for (let i = 0; i < s.length; i++) {
98	    h ^= s.charCodeAt(i);
99	    h = Math.imul(h, 0x01000193);
100	  }
101	  return h >>> 0;
102	}
103	
104	/**
105	 * The simple sampler: tests track first, then judge-only (never "none"); round-robin across terciles; within a
106	 * tercile, the order is a hash of the seed and the task id. The same inputs always give the same ids.
107	 */
108	export function simpleSample(tasks: TaskSummary[], max: number, exclude: readonly string[], seed: string): string[] {
109	  const skip = new Set(exclude);
110	  const picked: string[] = [];
111	  for (const track of TRACK_ORDER) {
112	    const buckets = TERCILE_ORDER.map((tercile) =>
113	      tasks
114	        .filter((t) => t.track === track && t.tercile === tercile && !skip.has(t.id))
115	        .sort((a, b) => hash32(seed + a.id) - hash32(seed + b.id) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0)),
116	    );
117	    let progressed = true;
118	    while (picked.length < max && progressed) {
119	      progressed = false;
120	      for (const bucket of buckets) {
121	        if (picked.length === max) break;
122	        const next = bucket.shift();
123	        if (next) {
124	          picked.push(next.id);
125	          progressed = true;
126	        }
127	      }
128	    }
129	    if (picked.length === max) break;
130	  }
131	  return picked;
132	}
133	
134	/** Replay rows: memory for the run, plus the `replays` table when a database is given. */
135	class ReplayStore {
136	  private readonly rows = new Map<string, Replay>();
137	  private readonly db: Database | null;
138	
139	  constructor(dbPath: string | undefined) {
140	    if (dbPath === undefined) {
141	      this.db = null;
142	      return;
143	    }
144	    mkdirSync(dirname(dbPath), { recursive: true });
145	    this.db = new Database(dbPath, { create: true });
146	    this.db.exec("PRAGMA journal_mode = WAL");
147	    this.db.exec(`CREATE TABLE IF NOT EXISTS replays (
148	      id TEXT PRIMARY KEY, plan_id TEXT NOT NULL, setup_id TEXT NOT NULL, json TEXT NOT NULL)`);
149	  }
150	
151	  put(rows: Replay[]): void {
152	    for (const r of rows) {
153	      this.rows.set(r.id, r);
154	      this.db
155	        ?.query("INSERT OR REPLACE INTO replays (id, plan_id, setup_id, json) VALUES (?, ?, ?, ?)")
156	        .run(r.id, r.plan_id, r.setup_id, JSON.stringify(r));
157	    }
158	  }
159	
160	  list(planId: string, setup?: string): Replay[] {
161	    const stored = this.db
162	      ? this.db
163	          .query<{ json: string }, [string, string | null, string | null]>(
164	            "SELECT json FROM replays WHERE plan_id = ? AND (? IS NULL OR setup_id = ?) ORDER BY rowid",
165	          )
166	          .all(planId, setup ?? null, setup ?? null)
167	          .map((r) => JSON.parse(r.json) as Replay)
168	      : [];
169	    const merged = new Map(stored.map((r) => [r.id, r]));
170	    for (const r of this.rows.values()) {
171	      if (r.plan_id === planId && (setup === undefined || r.setup_id === setup)) merged.set(r.id, r);
172	    }
173	    return [...merged.values()];
174	  }
175	}
176	
177	/** A transcript as the replay run reads it: stream-json lines, or the one result object of --output-format json. */
178	function readTranscript(path: string): Transcript {
179	  const text = readFileSync(path, "utf8");
180	  const t = parseTranscript(text);
181	  if (t.turns > 0 || t.result !== null || !text.trim()) return t;
182	  try {
183	    const j = JSON.parse(text);
184	    return parseTranscript((Array.isArray(j) ? j : [j]).map((e) => JSON.stringify(e)).join("\n"));
185	  } catch {
186	    return t;
187	  }
188	}
189	
190	/**
191	 * Failure codes for one failed replay: the taxonomy over its transcript and grade, plus the codes the run recorded.
192	 * The run recorded codes the taxonomy cannot re-derive here (F1 and F7 need the grader's violations, a forced code
193	 * needs the harness's error kind), so those keep the run's own reason.
194	 */
195	function failuresOf(r: Replay): Classified[] {
196	  if (r.failure_codes.includes(FailureCode.F6)) return [{ code: FailureCode.F6, evidence: [r.error ?? "environment error"] }];
197	  const path = r.transcript_ref;
198	  const onDisk = path !== null && existsSync(path);
199	  const found: Classified[] = [];
200	  if (path !== null && onDisk) {
201	    const t = readTranscript(path);
202	    const grade: GradeResult | null =
203	      r.verdict === "no_changes" || r.verdict === "agent_error"
204	        ? null
205	        : { hiddenPass: r.hidden_pass !== false, suitePass: r.suite_pass !== false, scopeOk: r.scope_ok !== false, violations: [], perTest: [] };
206	    // A result-only transcript carries no tool calls, so it is no evidence for F2.
207	    found.push(...classify({ verdict: r.verdict }, grade, t).filter((c) => t.turns > 0 || c.code !== FailureCode.F2));
208	  }
209	  for (const code of r.failure_codes) {
210	    if (found.some((c) => c.code === code)) continue;
211	    const why = r.error ? ` (${r.error})` : "";
212	    found.push({ code, evidence: [onDisk ? `recorded by the replay run${why}` : `transcript not on disk; recorded by the replay run${why}`] });
213	  }
214	  return found.sort((a, b) => FAILURE_ORDER.indexOf(a.code) - FAILURE_ORDER.indexOf(b.code));
215	}
216	
217	/** Writes reports/<slug>/promotion.json: the latest promotion decision for this repo. */
218	function writePromotion(reportsDir: string, repo: string, doc: Record<string, unknown>): void {
219	  const dir = join(reportsDir, reviewSlug(repo));
220	  mkdirSync(dir, { recursive: true });
221	  writeFileSync(join(dir, "promotion.json"), JSON.stringify(doc, null, 2) + "\n");
222	}
223	
224	/** The tool backend over the modules that exist today. The coordinator's ToolBackend contract is in ./tools.ts. */
225	export function defaultBackend(opts: DefaultBackendOptions = {}): ToolBackend {
226	  const cacheDir = resolve(opts.cacheDir ?? ".roster/cache");
227	  const reportsDir = resolve(opts.reportsDir ?? "reports");
228	  const store = new ReplayStore(opts.dbPath === undefined ? undefined : resolve(opts.dbPath));
229	  const replay = opts.replay ?? {};
230	  const runner = replayRunner({ cacheDir, ...replay });
231	  const readJson = <T>(repo: string, file: string): T | null => {
232	    const p = join(reportsDir, reviewSlug(repo), file);
233	    return existsSync(p) ? (JSON.parse(readFileSync(p, "utf8")) as T) : null;
234	  };
235	
236	  const listTasks = async (repo: string, setup?: string): Promise<TaskSummary[]> => {
237	    const view = await loadRepo(repo, cacheDir, readJson<Outcome[]>(repo, "outcomes.json") ?? []);
238	    const turns = turnCounter(view.repoPath);
239	    const checkpointOf = new Map(view.sessions.map((s) => [s.id, s.checkpoint_id]));
240	    return view.tasks
241	      .filter((t) => setup === undefined || t.setupId === setup)
242	      .map((t) => {
243	        const checkpoint = checkpointOf.get(t.id);
244	        return {
245	          id: t.id,
246	          setup: t.setupId,
247	          track: t.track,
248	          tercile: t.tercile,
249	          userPrompts: t.userPrompts,
250	          originalTurns: checkpoint ? turns(checkpoint, t.id) : null,
251	        };
252	      });
253	  };
254	
255	  return {
256	    async ingestRepo({ repo }) {
257	      const f = await fetchCheckpoints(repo, { cacheDir });
258	      if (f.backend === "none") throw new ToolError("no Entire checkpoints found in this repo");
259	      const sessions = parseCheckpoints(f.repoPath, f.backend === "refs" ? "git-refs" : "branch");
260	      const counts: Record<string, number> = {};
261	      for (const s of sessions) {
262	        const id = identify(s, f.repoPath).setupId ?? "unknown";
263	        counts[id] = (counts[id] ?? 0) + 1;
264	      }
265	      return { backend: f.backend, head: f.headSha, sessions: sessions.length, sessions_per_setup: counts };
266	    },
267	
268	    async getScorecard({ repo }) {
269	      const review = readJson<Review>(repo, "review.json");
270	      if (!review) throw new ToolError(`no review for ${repo}; run \`roster review ${repo} --observational\` first`);
271	      const sessions = readJson<Session[]>(repo, "sessions.json") ?? [];
272	      const outcomes = readJson<Outcome[]>(repo, "outcomes.json") ?? [];
273	      return { review, setups: summarizeSetups(sessions, outcomes) };
274	    },
275	
276	    listTasks: ({ repo, setup }) => listTasks(repo, setup),
277	
278	    async sampleTasks({ repo, max, exclude }) {
279	      try {
280	        const suspect = readJson<Review>(repo, "review.json")?.suspect ?? undefined;
281	        const tasks = await listTasks(repo, suspect);
282	        return simpleSample(tasks, max, exclude, reviewSlug(repo));
283	      } catch (err) {
284	        const why = err instanceof Error ? err.message : String(err);
285	        throw new NotAvailableError(`stratified sampling for ${repo} (${why}); name the task ids explicitly`);
286	      }
287	    },
288	
289	    async runReplays(a) {
290	      const batch = await runner(a);
291	      store.put(batch.replays);
292	      return batch;
293	    },
294	
295	    async getReplayResults({ plan_id, setup }) {
296	      return store.list(plan_id, setup);
297	    },
298	
299	    async rerun({ plan_id, task, setup, max_cost_usd }) {
300	      const attempt = Math.max(0, ...store.list(plan_id, setup).filter((r) => r.task_session_id === task).map((r) => r.attempt)) + 1;
301	      if (attempt > MAX_ATTEMPTS) throw new ToolError(`${task} under ${setup} has ${MAX_ATTEMPTS} attempts already (k = ${MAX_ATTEMPTS})`);
302	      if (!replay.repo) throw new Error("no repo configured for replays");
303	      const view = await loadRepo(replay.repo, cacheDir, []);
304	      const planned = view.tasks.find((t) => t.id === task);
305	      if (!planned) throw new ToolError(`no replayable task for session ${task}`);
306	      const known = loadSetups(replay.setupsRoot ?? process.cwd(), replay.env ?? process.env).find((s) => s.id === setup);
307	      if (!known) throw new ToolError(`unknown setup ${setup}`);
308	
309	      const skipped: SkippedRun[] = [];
310	      const replays = await runReplays({
311	        repo: view.repoPath,
312	        tasks: [planned],
313	        setups: [known],
314	        workRoot: resolve(replay.workRoot ?? defaultWorkRoot()),
315	        parallel: replay.parallel,
316	        maxCostUsd: max_cost_usd,
317	        harness: replay.harness,
318	        testCmd: replay.testCmd,
319	        planId: plan_id,
320	        attempt,
321	        onSkip: (s) => skipped.push(s),
322	      });
323	      if (replays.length === 0 && skipped.length > 0) throw new ToolError(`not run: ${skipped.map((s) => s.reason).join("; ")}`);
324	      store.put(replays);
325	      return { replays, cost_usd: replays.reduce((s, r) => s + (r.cost_usd ?? 0), 0), skipped } as ReplayBatch;
326	    },
327	
328	    async classifyFailures({ plan_id, setup }) {
329	      const rows = store.list(plan_id, setup);
330	      const failed = rows.filter((r) => r.verdict !== "pass");
331	      const replays = failed.map((r) => ({
332	        id: r.id,
333	        task: r.task_session_id,
334	        attempt: r.attempt,
335	        verdict: r.verdict,
336	        failures: failuresOf(r),
337	      }));
338	      const by_code: Record<string, number> = {};
339	      for (const r of replays) for (const f of r.failures) by_code[f.code] = (by_code[f.code] ?? 0) + 1;
340	      return { setup, runs: rows.length, failed: failed.length, by_code, replays };
341	    },
342	
343	    async gate({ plan_id, candidate, incumbent, budget_usd }) {
344	      if (incumbent === null) throw new ToolError("the plan names no incumbent (suspect), so there is nothing to gate against");
345	      const inc = store.list(plan_id, incumbent);
346	      const cand = store.list(plan_id, candidate);
347	      // Only tasks both sides ran can split; a candidate that never ran a task is left to the gate's own reasons.
348	      const candTasks = new Set(cand.map((r) => r.task_session_id));
349	      const both = new Set(inc.map((r) => r.task_session_id).filter((t) => candTasks.has(t)));
350	      const open = discordant(inc, cand).filter((d) => both.has(d.task_session_id));
351	      if (open.length > 0) {
352	        const todo = open.map((d) => `${d.task_session_id} under ${d.rerun.map((s) => (s === "incumbent" ? incumbent : candidate)).join(" and ")}`);
353	        throw new ToolError(`the sides still split; rerun first: ${todo.join("; ")}`);
354	      }
355	      const res = decideGate(inc, cand, { budget: budget_usd });
356	      return {
357	        id: `${plan_id}:${candidate}`,
358	        plan_id,
359	        candidate,
360	        verdict: res.verdict,
361	        reasons: res.reasons,
362	        failed_tasks: [...new Set([...res.regressions, ...res.scope_violations])],
363	        trace_url: null,
364	      };
365	    },
366	
367	    async promote({ repo, candidate, decision, from }) {
368	      if (decision.candidate !== candidate || decision.verdict !== "promote") {
369	        throw new ToolError(`the gate did not approve ${candidate}`);
370	      }
371	      const doc = { promoted: candidate, from, reasons: decision.reasons, at: new Date().toISOString() };
372	      writePromotion(reportsDir, repo, doc);
373	      return doc;
374	    },
375	
376	    async revert({ repo, setup, reason }) {
377	      const doc = { promoted: null, from: setup, reasons: [reason], at: new Date().toISOString() };
378	      writePromotion(reportsDir, repo, doc);
379	      return doc;
380	    },
381	  };
382	}
