1	// In-process tools the coordinator model may call (DESIGN.md §"Coordinator tools").
2	// Each tool validates its arguments, runs inside a TOOL span, and answers with JSON. Bad calls get an error
3	// message back, never a crash. The gate decides what ships: `promote` refuses any candidate the gate did not approve.
4	import { ATTR } from "../obs/attributes.ts";
5	import { type SpanAttrs, withSpan } from "../obs/index.ts";
6	import { FailureCode, type GateDecision, type Replay } from "../types.ts";
7	import type { ToolCall, ToolSpec } from "../llm/types.ts";
8	import { checkPlan, type PlanRevision } from "./plan.ts";
9	
10	// The real backend lives in ./backend.ts; it is re-exported here so the coordinator's default stays one import.
11	export { defaultBackend, type DefaultBackendOptions } from "./backend.ts";
12	
13	/** A gate decision as the coordinator records it: every rejection names its failed tasks. */
14	export interface Decision extends GateDecision {
15	  failed_tasks: string[];
16	}
17	
18	export type FinishOutcome = "promoted" | "no_better_setup";
19	
20	/** Everything a run has decided so far. JSON-serialisable: it is snapshotted into the events log for resume. */
21	export interface RunState {
22	  plans: PlanRevision[];
23	  decisions: Decision[];
24	  promoted: string | null;
25	  reverted: string[];
26	  /** Tasks that hit F6; excluded from later plans. */
27	  excludedTasks: string[];
28	  replayUsd: number;
29	  finished: { outcome: FinishOutcome; summary: string } | null;
30	  /** Messages for the coordinator to pass to the model before its next turn (replan requests). */
31	  notes: string[];
32	}
33	
34	export function initialState(): RunState {
35	  return { plans: [], decisions: [], promoted: null, reverted: [], excludedTasks: [], replayUsd: 0, finished: null, notes: [] };
36	}
37	
38	export interface ReplayBatch {
39	  replays: Replay[];
40	  cost_usd: number;
41	}
42	
43	/** A replayable task as list_tasks shows it. originalTurns is null when the checkpoint metadata does not record it. */
44	export interface TaskSummary {
45	  id: string;
46	  setup: string | null;
47	  track: "tests" | "judge-only" | "none";
48	  tercile: 1 | 2 | 3 | null;
49	  userPrompts: number;
50	  originalTurns: number | null;
51	}
52	
53	/** What the tools wrap. Methods that throw NotAvailableError report "not available yet" to the model. */
54	export interface ToolBackend {
55	  ingestRepo(a: { repo: string }): Promise<unknown>;
56	  getScorecard(a: { repo: string }): Promise<unknown>;
57	  /** Replayable tasks, optionally of one setup. Optional: a backend without it answers "not available yet". */
58	  listTasks?(a: { repo: string; setup?: string }): Promise<TaskSummary[]>;
59	  /** A stratified task sample (≤ max), used when the model plans without naming tasks. */
60	  sampleTasks(a: { repo: string; max: number; exclude: string[] }): Promise<string[]>;
61	  runReplays(a: { plan_id: string; tasks: string[]; setups: string[]; max_cost_usd: number }): Promise<ReplayBatch>;
62	  getReplayResults(a: { plan_id: string; setup?: string }): Promise<Replay[]>;
63	  rerun(a: { plan_id: string; task: string; setup: string; max_cost_usd: number }): Promise<ReplayBatch>;
64	  classifyFailures(a: { plan_id: string; setup: string }): Promise<unknown>;
65	  /** Deterministic gate (DESIGN.md §"Gate"). The incumbent and budget come from the plan. The coordinator cannot override it. */
66	  gate(a: {
67	    plan_id: string;
68	    candidate: string;
69	    incumbent: string | null;
70	    budget_usd: number;
71	  }): Promise<Omit<Decision, "failed_tasks"> & { failed_tasks?: string[] }>;
72	  promote(a: { repo: string; candidate: string; decision: Decision; from: string | null }): Promise<unknown>;
73	  revert(a: { repo: string; setup: string; reason: string }): Promise<unknown>;
74	}
75	
76	export class NotAvailableError extends Error {
77	  constructor(what: string) {
78	    super(`not available yet: ${what}`);
79	  }
80	}
81	
82	export interface ToolContext {
83	  runId: string;
84	  repo: string;
85	  budgetUsd: number;
86	  /** LLM plus replay spend so far. */
87	  spentUsd: () => number;
88	}
89	
90	interface ToolDef {
91	  spec: ToolSpec;
92	  run(args: Record<string, unknown>, state: RunState, ctx: ToolContext, backend: ToolBackend, span: SpanSink): Promise<unknown>;
93	}
94	
95	interface SpanSink {
96	  attrs: SpanAttrs;
97	}
98	
99	/** An error the model caused (bad arguments, wrong order). Reported back to it as `{ok:false,error}`. */
100	export class ToolError extends Error {}
101	
102	const str = (description: string) => ({ type: "string", description });
103	const strs = (description: string) => ({ type: "array", items: { type: "string" }, description });
104	const obj = (properties: Record<string, unknown>, required: string[] = []) => ({
105	  type: "object",
106	  properties,
107	  required,
108	  additionalProperties: false,
109	});
110	
111	export function currentPlan(state: RunState): PlanRevision | null {
112	  return state.plans.at(-1) ?? null;
113	}
114	
115	export function planId(runId: string, plan: PlanRevision): string {
116	  return `${runId}-p${plan.revision}`;
117	}
118	
119	function requirePlan(state: RunState): PlanRevision {
120	  const plan = currentPlan(state);
121	  if (!plan) throw new ToolError("no plan yet: call plan_replays first");
122	  return plan;
123	}
124	
125	function remaining(ctx: ToolContext): number {
126	  const left = ctx.budgetUsd - ctx.spentUsd();
127	  if (left <= 0) throw new ToolError(`budget exhausted: spent $${ctx.spentUsd().toFixed(4)} of $${ctx.budgetUsd}`);
128	  return left;
129	}
130	
131	/** Records replay spend and F6 exclusions from a batch of replays. */
132	function absorb(state: RunState, replays: Replay[], cost: number): void {
133	  state.replayUsd += Number.isFinite(cost) && cost > 0 ? cost : 0;
134	  const f6 = [...new Set(replays.filter((r) => r.failure_codes.includes(FailureCode.F6)).map((r) => r.task_session_id))].filter(
135	    (t) => !state.excludedTasks.includes(t),
136	  );
137	  if (f6.length) {
138	    state.excludedTasks.push(...f6);
139	    state.notes.push(
140	      `F6 (environment or setup error) on task(s) ${f6.join(", ")}. They are excluded. Replan: call plan_replays with a resampled task set.`,
141	    );
142	  }
143	}
144	
145	const TOOLS: ToolDef[] = [
146	  {
147	    spec: {
148	      name: "ingest_repo",
149	      description: "Fetch the repo's Entire checkpoints and list its sessions and setups.",
150	      parameters: obj({}),
151	    },
152	    run: (_a, _s, ctx, b) => b.ingestRepo({ repo: ctx.repo }),
153	  },
154	  {
155	    spec: {
156	      name: "get_scorecard",
157	      description: "The observational (level A) scorecard per setup, and the review's suspect label.",
158	      parameters: obj({}),
159	    },
160	    run: (_a, _s, ctx, b) => b.getScorecard({ repo: ctx.repo }),
161	  },
162	  {
163	    spec: {
164	      name: "list_tasks",
165	      description:
166	        "Replayable tasks from the repo's sessions: id, setup, track (tests, judge-only or none), tercile, user prompts and original turns. Name task ids from here in plan_replays.",
167	      parameters: obj({ setup: str("Only this setup's tasks.") }),
168	    },
169	    async run(a, _s, ctx, b) {
170	      if (!b.listTasks) throw new NotAvailableError("list_tasks");
171	      const tasks = await b.listTasks({ repo: ctx.repo, setup: a.setup as string | undefined });
172	      return { count: tasks.length, tasks };
173	    },
174	  },
175	  {
176	    spec: {
177	      name: "plan_replays",
178	      description:
179	        "Write or revise plan.json. Give a one-paragraph rationale, the suspect setup, ≤ 3 candidate setup ids and ≤ 12 task session ids (omit tasks for a stratified sample). Call again to replan after a gate rejection or F6.",
180	      parameters: obj(
181	        {
182	          rationale: str("One paragraph: why these tasks and candidates."),
183	          suspect: { type: ["string", "null"], description: "The suspect (incumbent) setup id, or null." },
184	          candidates: strs("Candidate setup ids, at most 3."),
185	          tasks: strs("Task session ids, at most 12, stratified by difficulty tercile."),
186	          stop_rules: strs("Stop rules. Defaults apply when omitted."),
187	          budget_usd: { type: "number", description: "May lower, never raise, the run budget." },
188	          reason: str("Why you are (re)planning."),
189	        },
190	        ["rationale", "candidates"],
191	      ),
192	    },
193	    async run(a, state, ctx, b) {
194	      const input = { ...a };
195	      const sampled = input.tasks === undefined;
196	      if (input.tasks === undefined) {
197	        input.tasks = await b.sampleTasks({ repo: ctx.repo, max: 12, exclude: state.excludedTasks });
198	      }
199	      const rejected = new Set(state.decisions.filter((d) => d.verdict === "reject").map((d) => d.candidate));
200	      const check = checkPlan(input, {
201	        budgetUsd: ctx.budgetUsd,
202	        previous: state.plans,
203	        excludedTasks: new Set(state.excludedTasks),
204	        rejected,
205	        reason: typeof a.reason === "string" && a.reason ? a.reason : state.plans.length ? "replan" : "initial",
206	      });
207	      if (!check.ok) throw new ToolError(`plan rejected: ${check.errors.join("; ")}`);
208	      state.plans.push(check.revision);
209	      return { plan_id: planId(ctx.runId, check.revision), ...check.revision, ...(sampled ? { sampled_by: "simple sampler" } : {}) };
210	    },
211	  },
212	  {
213	    spec: {
214	      name: "run_replays",
215	      description: "Replay the plan's tasks at their parent commits under the given setups (include the incumbent as control).",
216	      parameters: obj({ setups: strs("Setup ids to replay."), tasks: strs("Subset of the plan's tasks; default all.") }, ["setups"]),
217	    },
218	    async run(a, state, ctx, b, span) {
219	      const plan = requirePlan(state);
220	      const setups = a.setups as string[];
221	      if (setups.length === 0) throw new ToolError("setups: at least one setup id is required");
222	      const tasks = (a.tasks as string[] | undefined) ?? plan.body.tasks;
223	      const off = tasks.filter((t) => !plan.body.tasks.includes(t));
224	      if (off.length) throw new ToolError(`tasks not in the current plan: ${off.join(", ")}`);
225	      const batch = await b.runReplays({ plan_id: planId(ctx.runId, plan), tasks, setups, max_cost_usd: remaining(ctx) });
226	      absorb(state, batch.replays, batch.cost_usd);
227	      span.attrs.costUsd = batch.cost_usd;
228	      return batch;
229	    },
230	  },
231	  {
232	    spec: {
233	      name: "get_replay_results",
234	      description: "Replay rows for the current plan, optionally for one setup.",
235	      parameters: obj({ setup: str("Setup id.") }),
236	    },
237	    async run(a, state, ctx, b) {
238	      const plan = requirePlan(state);
239	      const replays = await b.getReplayResults({ plan_id: planId(ctx.runId, plan), setup: a.setup as string | undefined });
240	      absorb(state, replays, 0);
241	      return replays;
242	    },
243	  },
244	  {
245	    spec: {
246	      name: "rerun",
247	      description: "Rerun one task under one setup (for grader/judge disagreement or a split, up to k = 3).",
248	      parameters: obj({ task: str("Task session id."), setup: str("Setup id.") }, ["task", "setup"]),
249	    },
250	    async run(a, state, ctx, b, span) {
251	      const plan = requirePlan(state);
252	      if (!plan.body.tasks.includes(a.task as string)) throw new ToolError(`${a.task} is not in the current plan`);
253	      if (![plan.body.suspect, ...plan.body.candidates].includes(a.setup as string)) {
254	        throw new ToolError(`${a.setup} is not in the current plan`);
255	      }
256	      span.attrs.task = a.task as string;
257	      span.attrs.setup = a.setup as string;
258	      const batch = await b.rerun({
259	        plan_id: planId(ctx.runId, plan),
260	        task: a.task as string,
261	        setup: a.setup as string,
262	        max_cost_usd: remaining(ctx),
263	      });
264	      absorb(state, batch.replays, batch.cost_usd);
265	      span.attrs.costUsd = batch.cost_usd;
266	      return batch;
267	    },
268	  },
269	  {
270	    spec: {
271	      name: "classify_failures",
272	      description: "Failure taxonomy (F1–F7) for one setup's replays in the current plan.",
273	      parameters: obj({ setup: str("Setup id.") }, ["setup"]),
274	    },
275	    async run(a, state, ctx, b) {
276	      const plan = requirePlan(state);
277	      return b.classifyFailures({ plan_id: planId(ctx.runId, plan), setup: a.setup as string });
278	    },
279	  },
280	  {
281	    spec: {
282	      name: "propose_rules_candidate",
283	      description: "Patch the suspect's rules file from its top failure codes into a new candidate.",
284	      parameters: obj({ setup: str("Setup id to mutate."), failure_codes: strs("Failure codes to answer.") }),
285	    },
286	    async run() {
287	      throw new NotAvailableError("propose_rules_candidate (src/candidates is not built)");
288	    },
289	  },
290	  {
291	    spec: {
292	      name: "gate",
293	      description: "Run the deterministic gate for one candidate against the incumbent on the current plan. Its verdict is final.",
294	      parameters: obj({ candidate: str("Candidate setup id.") }, ["candidate"]),
295	    },
296	    async run(a, state, ctx, b, span) {
297	      const plan = requirePlan(state);
298	      const candidate = a.candidate as string;
299	      if (!plan.body.candidates.includes(candidate)) throw new ToolError(`${candidate} is not a candidate in the current plan`);
300	      span.attrs.setup = candidate;
301	      const raw = await withSpan("GUARDRAIL", "gate", { setup: candidate, evidenceLevel: "B" }, () =>
302	        b.gate({
303	          plan_id: planId(ctx.runId, plan),
304	          candidate,
305	          incumbent: plan.body.suspect,
306	          budget_usd: plan.body.budget_usd,
307	        }),
308	      );
309	      const decision: Decision = { ...raw, failed_tasks: raw.failed_tasks ?? [] };
310	      if (
311	        decision.candidate !== candidate ||
312	        decision.plan_id !== planId(ctx.runId, plan) ||
313	        (decision.verdict !== "promote" && decision.verdict !== "reject")
314	      ) {
315	        throw new Error(`gate returned a malformed decision for ${candidate}`);
316	      }
317	      state.decisions.push(decision);
318	      if (decision.verdict === "reject") {
319	        state.notes.push(
320	          `The gate rejected ${candidate}: ${decision.reasons.join("; ") || "no reasons given"}. Replan: call plan_replays with the next candidate, or finish with no_better_setup.`,
321	        );
322	      }
323	      return decision;
324	    },
325	  },
326	  {
327	    spec: {
328	      name: "promote",
329	      description: "Promote a candidate. Only works for a candidate the gate approved on the current plan.",
330	      parameters: obj({ candidate: str("Candidate setup id.") }, ["candidate"]),
331	    },
332	    async run(a, state, ctx, b, span) {
333	      const plan = requirePlan(state);
334	      const candidate = a.candidate as string;
335	      span.attrs.setup = candidate;
336	      if (state.promoted) throw new ToolError(`${state.promoted} is already promoted`);
337	      const decision = state.decisions.find(
338	        (d) => d.candidate === candidate && d.plan_id === planId(ctx.runId, plan) && d.verdict === "promote",
339	      );
340	      if (!decision) throw new ToolError(`the gate has not approved ${candidate} on the current plan; the gate decides what ships`);
341	      const res = await b.promote({ repo: ctx.repo, candidate, decision, from: plan.body.suspect });
342	      state.promoted = candidate;
343	      return res;
344	    },
345	  },
346	  {
347	    spec: {
348	      name: "revert",
349	      description: "Revert a previously promoted setup.",
350	      parameters: obj({ setup: str("Setup id."), reason: str("Why.") }, ["setup", "reason"]),
351	    },
352	    async run(a, state, ctx, b, span) {
353	      span.attrs.setup = a.setup as string;
354	      const res = await b.revert({ repo: ctx.repo, setup: a.setup as string, reason: a.reason as string });
355	      state.reverted.push(a.setup as string);
356	      if (state.promoted === a.setup) state.promoted = null;
357	      return res;
358	    },
359	  },
360	  {
361	    spec: {
362	      name: "finish",
363	      description:
364	        "End the run. outcome is \"promoted\" only after a successful promote; otherwise \"no_better_setup\" (a valid result). Summarise only what tools returned.",
365	      parameters: obj(
366	        { outcome: { type: "string", enum: ["promoted", "no_better_setup"] }, summary: str("What the tools showed.") },
367	        ["outcome", "summary"],
368	      ),
369	    },
370	    async run(a, state) {
371	      const outcome = a.outcome as FinishOutcome;
372	      if (outcome === "promoted" && !state.promoted) throw new ToolError("nothing was promoted; finish with no_better_setup");
373	      if (outcome === "no_better_setup" && state.promoted) throw new ToolError(`${state.promoted} was promoted; finish with promoted`);
374	      state.finished = { outcome, summary: a.summary as string };
375	      return state.finished;
376	    },
377	  },
378	];
379	
380	export const TOOL_SPECS: ToolSpec[] = TOOLS.map((t) => t.spec);
381	
382	type Prop = { type?: string | string[]; items?: { type: string }; enum?: string[] };
383	
384	/** Checks parsed arguments against a tool's parameter schema. Returns the problems, empty when valid. */
385	export function validateArgs(spec: ToolSpec, args: unknown): string[] {
386	  if (typeof args !== "object" || args === null || Array.isArray(args)) return ["arguments must be a JSON object"];
387	  const rec = args as Record<string, unknown>;
388	  const props = (spec.parameters.properties ?? {}) as Record<string, Prop>;
389	  const required = (spec.parameters.required ?? []) as string[];
390	  const errors: string[] = [];
391	  for (const r of required) if (rec[r] === undefined) errors.push(`missing required argument "${r}"`);
392	  for (const [k, v] of Object.entries(rec)) {
393	    const p = props[k];
394	    if (!p) {
395	      errors.push(`unknown argument "${k}"`);
396	      continue;
397	    }
398	    if (v === undefined) continue;
399	    const types = Array.isArray(p.type) ? p.type : [p.type];
400	    const ok = types.some((t) =>
401	      t === "string"
402	        ? typeof v === "string"
403	        : t === "number"
404	          ? typeof v === "number" && Number.isFinite(v)
405	          : t === "null"
406	            ? v === null
407	            : t === "array"
408	              ? Array.isArray(v) && v.every((x) => typeof x === "string")
409	              : true,
410	    );
411	    if (!ok) errors.push(`argument "${k}" must be ${types.join(" or ")}${p.items ? ` of ${p.items.type}` : ""}`);
412	    else if (p.enum && !p.enum.includes(v as string)) errors.push(`argument "${k}" must be one of ${p.enum.join(", ")}`);
413	  }
414	  return errors;
415	}
416	
417	const MAX_RESULT_CHARS = 20_000;
418	
419	export interface ToolOutcome {
420	  /** The tool message content sent back to the model. */
421	  content: string;
422	  ok: boolean;
423	}
424	
425	/**
426	 * Runs one tool call from the model. Unknown tools, malformed JSON, bad arguments, tool misuse and backend
427	 * failures all come back as `{"ok":false,"error":...}`; this function does not throw.
428	 */
429	export async function executeToolCall(
430	  call: ToolCall,
431	  state: RunState,
432	  ctx: ToolContext,
433	  backend: ToolBackend,
434	): Promise<ToolOutcome> {
435	  const reply = (ok: boolean, body: Record<string, unknown>): ToolOutcome => {
436	    let content = JSON.stringify({ ok, ...body });
437	    if (content.length > MAX_RESULT_CHARS) content = `${content.slice(0, MAX_RESULT_CHARS)}… [truncated]`;
438	    return { ok, content };
439	  };
440	  const def = TOOLS.find((t) => t.spec.name === call.name);
441	  if (!def) return reply(false, { error: `unknown tool "${call.name}". Available: ${TOOL_SPECS.map((t) => t.name).join(", ")}` });
442	  let args: unknown;
443	  try {
444	    args = call.arguments.trim() === "" ? {} : JSON.parse(call.arguments);
445	  } catch (err) {
446	    return reply(false, { error: `arguments are not valid JSON (${err instanceof Error ? err.message : String(err)})` });
447	  }
448	  const problems = validateArgs(def.spec, args);
449	  if (problems.length) return reply(false, { error: `invalid arguments for ${call.name}: ${problems.join("; ")}` });
450	
451	  const sink: SpanSink = { attrs: { repo: ctx.repo } };
452	  return withSpan("TOOL", call.name, sink.attrs, async (span) => {
453	    try {
454	      const result = await def.run(args as Record<string, unknown>, state, ctx, backend, sink);
455	      if (sink.attrs.setup !== undefined) span.setAttribute(ATTR.setup, sink.attrs.setup);
456	      if (sink.attrs.task !== undefined) span.setAttribute(ATTR.task, sink.attrs.task);
457	      if (sink.attrs.costUsd !== undefined) span.setAttribute(ATTR.costUsd, sink.attrs.costUsd);
458	      return reply(true, { result: result ?? null });
459	    } catch (err) {
460	      const msg = err instanceof Error ? err.message : String(err);
461	      return reply(false, { error: err instanceof ToolError || err instanceof NotAvailableError ? msg : `${call.name} failed: ${msg}` });
462	    }
463	  });
464	}
465	
466

